<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';AuthService::boot();$user=AuthService::requireLogin();$gid=(int)($_GET['game']??$_POST['game_id']??0);if($gid<1){header('Location: ./');exit;}$error=null;$notice=null;
try{$membership=LobbyService::lobbyState($gid,(int)$user['user_id']);if($membership['game']['status']==='LOBBY'){header('Location: lobby.php?game='.$gid);exit;}}catch(Throwable$e){http_response_code(403);die(e($e->getMessage()));}
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');if($action==='decide')LobbyService::choose($gid,(int)$user['user_id'],(int)$_POST['decision_id'],(string)$_POST['option_code']);if($action==='rate'){LobbyService::rate($gid,(int)$user['user_id'],(int)$_POST['rating'],(string)($_POST['review']??''));$notice='Thank you for rating this story.';}header('Location: play.php?game='.$gid.($notice?'&rated=1':''));exit;}catch(Throwable$e){$error=$e->getMessage();}}
try{LobbyService::tick($gid);}catch(Throwable$e){$error=($error?$error.' | ':'').$e->getMessage();}
$state=LobbyService::lobbyState($gid,(int)$user['user_id']);$sid=(int)$state['game']['simulation_id'];$snap=SimulationService::snapshot($sid);$sim=$snap['simulation'];$character=LobbyService::playerCharacter($gid,(int)$user['user_id']);if($character){foreach($snap['characters']as$c)if((int)$c['character_id']===(int)$character['character_id']){$character=$c;break;}}$rated=isset($_GET['rated']);
$playDuration=(int)($state['game']['play_duration_seconds']??$sim['duration_seconds']);$storyDuration=max(1,(int)$sim['duration_seconds']);$wallElapsed=0;if(!empty($state['game']['started_at_utc']))$wallElapsed=min($playDuration,max(0,time()-strtotime((string)$state['game']['started_at_utc'].' UTC')));if($sim['status']==='COMPLETE')$wallElapsed=$playDuration;
$displaySecond=static fn(int $storySecond):int=>(int)round($storySecond*$playDuration/$storyDuration);
$timeline=[];foreach($snap['world']as$w){$second=(int)$w['event_second'];$timeline[$second]??=['public'=>[],'personal'=>[]];$timeline[$second]['public'][]=['label'=>(string)$w['phase'],'title'=>(string)$w['headline'],'detail'=>(string)$w['event_text']];}if($character)foreach($character['history']as$h){$second=(int)$h['event_second'];$timeline[$second]??=['public'=>[],'personal'=>[]];$timeline[$second]['personal'][]=['label'=>ucwords(strtolower(str_replace('_',' ',(string)$h['history_type']))),'title'=>(string)$h['title'],'detail'=>(string)$h['detail_text']];}krsort($timeline,SORT_NUMERIC);
$outcome=[];if($sim['status']==='COMPLETE'){$q=db()->prepare('SELECT label_text,source_type,source_key FROM plot_outcome_dimensions WHERE plot_id=? AND active=1 ORDER BY sort_order,outcome_dimension_id');$q->execute([$sim['plot_id']]);foreach($q->fetchAll()as$d){$v='UNKNOWN';if($d['source_type']==='FACTOR'){foreach($snap['factors']as$f)if($f['factor_code']===$d['source_key']){$n=(int)$f['current_value'];$v=$n<35?'LOW':($n<65?'MID':'HIGH');break;}}else{$s=GenericStateService::getByKey($sid,(string)$d['source_key']);if($s['exists'])$v=strtoupper((string)$s['value']);}$outcome[]=trim($d['label_text'].' '.$v);}}
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function game_time(int $seconds):string{if($seconds>=86400){$days=intdiv($seconds,86400);return$days.'d '.gmdate('H:i:s',$seconds%86400);}if($seconds>=3600)return gmdate('G:i:s',$seconds);return gmdate('i:s',$seconds);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($sim['title'])?> · Toinky</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#e9edf3}*{box-sizing:border-box}body{margin:0}.bar{position:sticky;top:0;z-index:10;background:#111827;color:#fff;padding:13px 18px}.barin,.shell{max-width:1180px;margin:auto}.barin{display:flex;justify-content:space-between;align-items:center;gap:12px}.bar a{color:#fff}.shell{padding:22px 18px}.layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.65fr);gap:18px;align-items:start}.card{background:#fff;border:1px solid #d8e0ea;border-radius:15px;padding:19px;margin-bottom:16px}.private{background:#fff7ed;border-color:#fed7aa}.decision{border:2px solid #7c3aed;background:#f5f3ff}.option{display:block;width:100%;text-align:left;background:#fff;border:1px solid #c4b5fd;border-radius:9px;padding:11px;margin:8px 0;font:inherit;cursor:pointer}.btn{border:0;border-radius:9px;background:#4f46e5;color:#fff;padding:10px 14px;font:inherit;font-weight:800;cursor:pointer}.outcome{background:#ecfdf5;border:2px solid #6ee7b7}.outcome li{margin:6px 0}.error{background:#fee2e2;color:#991b1b;padding:12px;border-radius:10px}.progress{height:8px;background:#374151;border-radius:999px;overflow:hidden;width:180px}.progress span{display:block;height:100%;background:#818cf8}.muted,.timeline-time,.entry-label{color:#64748b}.timeline{display:grid;gap:12px}.timeline-row{border:1px solid #dbe3ec;border-radius:13px;padding:14px;background:#f8fafc}.timeline-time{font-size:12px;font-weight:800;margin-bottom:9px}.timeline-pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.timeline-pair.solo{grid-template-columns:1fr}.timeline-entry{background:#fff;border-radius:10px;padding:12px;border-left:4px solid #6366f1}.timeline-entry.personal{border-left-color:#f59e0b;background:#fffaf0}.entry-label{font-size:11px;text-transform:uppercase;letter-spacing:.05em;font-weight:800}.timeline-entry h3{font-size:15px;margin:5px 0}.timeline-entry p{margin:0;line-height:1.45}.live-note{font-size:12px;color:#64748b;margin-top:-8px;margin-bottom:14px}.decision-alert{display:inline-block;background:#7c3aed;color:#fff;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:850;margin-bottom:6px}@media(max-width:800px){.layout{grid-template-columns:1fr}.barin{align-items:flex-start;flex-wrap:wrap}.timeline-pair{grid-template-columns:1fr}}
</style></head><body><div id="game-live" data-status="<?=e($sim['status'])?>"><header class="bar"><div class="barin"><div><b><?=e($sim['title'])?></b><div class="muted"><?=e(ucwords(strtolower(str_replace('_',' ',$sim['current_phase']))))?> · <?=game_time($wallElapsed)?> / <?=game_time($playDuration)?></div></div><div class="progress"><span style="width:<?=min(100,round(100*$wallElapsed/max(1,$playDuration)))?>%"></span></div><a href="./">My Games</a></div></header><main class="shell" aria-live="polite"><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if($rated):?><p class="card">Thank you for rating this story.</p><?php endif;?>
<?php if($sim['status']==='COMPLETE'):?><section class="card outcome"><h1>The Story Is Complete</h1><ul><?php foreach($outcome as$o):?><li><?=e($o)?></li><?php endforeach;?></ul></section><?php endif;?>
<div class="layout"><div><section class="card"><h2>Live Story Timeline</h2><p class="live-note">Newest events appear first. Public events and your character’s experience share the same chronological row.</p><?php if(!$timeline):?><p class="muted">The story is beginning…</p><?php endif;?><div class="timeline"><?php foreach($timeline as$second=>$row):$both=!empty($row['public'])&&!empty($row['personal']);?><article class="timeline-row"><div class="timeline-time"><?=game_time($displaySecond((int)$second))?></div><div class="timeline-pair <?=$both?'':'solo'?>"><?php if($row['public']):?><div><?php foreach($row['public']as$item):?><section class="timeline-entry"><div class="entry-label">Everyone Can See · <?=e(ucwords(strtolower(str_replace('_',' ',$item['label']))))?></div><h3><?=e($item['title'])?></h3><p><?=e($item['detail'])?></p></section><?php endforeach;?></div><?php endif;?><?php if($row['personal']):?><div><?php foreach($row['personal']as$item):?><section class="timeline-entry personal"><div class="entry-label">Your Experience · <?=e($item['label'])?></div><h3><?=e($item['title'])?></h3><p><?=e($item['detail'])?></p></section><?php endforeach;?></div><?php endif;?></div></article><?php endforeach;?></div></section></div><aside>
<?php if($character):?><section class="card private"><small>Your Private Character View</small><h2><?=e($character['name'])?></h2><p><?=e($character['description'])?></p><p><b>Where You Are:</b> <?=e($character['current_location'])?></p><p><b>Your Goal:</b> <?=e($character['goal_text'])?></p><p><b>Your Fear:</b> <?=e($character['fear_text'])?></p><p><b>What Only You Know:</b><br><?=e($character['private_knowledge'])?></p></section>
<?php foreach($character['open_decisions']as$d):?><section class="card decision"><span class="decision-alert">Decision Available</span><h2>Choose What You Do</h2><p><?=e($d['prompt_text'])?></p><?php foreach($d['options']as$o):?><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="decide"><input type="hidden" name="decision_id" value="<?=(int)$d['decision_id']?>"><input type="hidden" name="option_code" value="<?=e($o['option_code'])?>"><button class="option"><b><?=e($o['label'])?></b><?php if(!empty($o['description'])):?><br><small><?=e($o['description'])?></small><?php endif;?></button></form><?php endforeach;?></section><?php endforeach;?>
<?php else:?><section class="card"><h2>Spectator View</h2><p>You did not select a character before the game began.</p></section><?php endif;?>
<?php if($sim['status']==='COMPLETE'):?><section class="card"><h2>Rate This Story</h2><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="rate"><label>Rating <select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> / 5</option><?php endfor;?></select></label><p><textarea name="review" rows="4" style="width:100%" placeholder="Optional review"></textarea></p><button class="btn">Save Rating</button></form></section><?php endif;?></aside></div></main></div>
<script>let liveBusy=false,liveTimer=null;async function refreshLiveGame(){if(liveBusy||document.hidden)return;liveBusy=true;try{const response=await fetch('play.php?game=<?=$gid?>&live=1',{cache:'no-store',headers:{'X-Toinky-Live':'1'}});if(!response.ok)return;const html=await response.text();const next=new DOMParser().parseFromString(html,'text/html').querySelector('#game-live');const current=document.querySelector('#game-live');if(next&&current){current.replaceWith(next);if(next.dataset.status!=='RUNNING'&&liveTimer){clearInterval(liveTimer);liveTimer=null;}}}catch(error){}finally{liveBusy=false;}}if(document.querySelector('#game-live')?.dataset.status==='RUNNING'){liveTimer=setInterval(refreshLiveGame,2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLiveGame();});}</script></body></html>
